1	/* Tailwind v4 — imports all base, components, and utilities */
2	@import "tailwindcss";
3	@import "tw-animate-css";
4	@import "shadcn/tailwind.css";
5	
6	/* IBM Plex Mono — portfolio body/UI font, via @fontsource */
7	@import "@fontsource/ibm-plex-mono/400.css";
8	@import "@fontsource/ibm-plex-mono/500.css";
9	@import "@fontsource/ibm-plex-mono/600.css";
10	
11	/* IBM Plex Sans — portfolio long-form/label font (bio copy, section labels, footer).
12	   Variable weight (100–700) so any font-weight utility actually takes effect,
13	   not just the handful of static cuts the non-variable package would ship. */
14	@import "@fontsource-variable/ibm-plex-sans/wght.css";
15	
16	/* ─── Font faces ──────────────────────────────────────────────────────────── */
17	
18	/* Geist Sans — variable font, covers all weights from 100–900 */
19	@font-face {
20	  font-family: "Geist Sans";
21	  src: url("/node_modules/geist/dist/fonts/geist-sans/Geist-Variable.woff2")
22	    format("woff2");
23	  font-weight: 100 900;
24	  font-style: normal;
25	  font-display: swap;
26	}
27	
28	/* Geist Mono — variable font, used only by the Undercurrent case-study
29	   sandbox (src/components/undercurrent-demo) for the secondary/technical
30	   text style the real design system uses (e.g. a DynamicBadge's monospace
31	   detail text). Declared globally alongside Geist Sans, same as every other
32	   font-face in this file, even though only one feature currently uses it. */
33	@font-face {
34	  font-family: "Geist Mono";
35	  src: url("/node_modules/geist/dist/fonts/geist-mono/GeistMono-Variable.woff2")
36	    format("woff2");
37	  font-weight: 100 900;
38	  font-style: normal;
39	  font-display: swap;
40	}
41	
42	/* Redaction 35 — portfolio headline font, self-hosted in /public/fonts/.
43	   Regular and Italic are true cuts (not synthetic), so they share one family
44	   name and map onto CSS's own font-style axis — the `italic` utility class
45	   switches to the correct file automatically. */
46	@font-face {
47	  font-family: "Redaction 35";
48	  src: url("/fonts/Redaction_35-Regular.woff2") format("woff2");
49	  font-weight: 400;
50	  font-style: normal;
51	  font-display: swap;
52	}
53	@font-face {
54	  font-family: "Redaction 35";
55	  src: url("/fonts/Redaction_35-Italic.woff2") format("woff2");
56	  font-weight: 400;
57	  font-style: italic;
58	  font-display: swap;
59	}
60	
61	@custom-variant dark (&:is(.dark *));
62	
63	@theme inline {
64	  /* font-sans     → Geist Sans (body text and UI) */
65	  --font-sans: "Geist Sans", sans-serif;
66	  /* font-mono     → IBM Plex Mono (portfolio page body/UI text) */
67	  --font-mono: "IBM Plex Mono", monospace;
68	  /* font-redaction  → Redaction 35 (portfolio headline only) */
69	  --font-redaction: "Redaction 35", serif;
70	  /* font-plex-sans  → IBM Plex Sans Variable (portfolio long-form/label text) */
71	  --font-plex-sans: "IBM Plex Sans Variable", sans-serif;
72	
73	  /* ─── Portfolio colors (codykeisler.me redesign) ─────────────────────────── */
74	  /* Use these as Tailwind utilities: bg-portfolio-bg, text-portfolio-ink, etc.
75	       Raw values live in :root / .dark below so theme switching is a variable
76	       swap — see the `dark` custom-variant above. */
77	  --color-portfolio-bg: var(--portfolio-bg);
78	  --color-portfolio-ink: var(--portfolio-ink);
79	  /* Single dim/secondary tone, used everywhere something needs to read as
80	       less prominent than portfolio-ink: section eyebrow labels, dates,
81	       taglines, footer copy, the nav breadcrumb badge, and footnotes. */
82	  --color-portfolio-muted: var(--portfolio-muted);
83	  --color-portfolio-accent: var(--portfolio-accent);
84	  /* Small tinted tile behind a keyboard-shortcut glyph (Enter / Esc / X / W)
85	       on bottom-nav action buttons, and the active-row tint in the top nav
86	       and side nav. Both are low-opacity ink tints, so they read on either
87	       theme's background without needing hand-picked light/dark hex pairs. */
88	  --color-portfolio-keycap: var(--portfolio-keycap);
89	  --color-portfolio-nav-active: var(--portfolio-nav-active);
90	
91	  --radius-sm: calc(var(--radius) * 0.6);
92	  --radius-md: calc(var(--radius) * 0.8);
93	  --radius-lg: var(--radius);
94	  --radius-xl: calc(var(--radius) * 1.4);
95	  --radius-2xl: calc(var(--radius) * 1.8);
96	  --radius-3xl: calc(var(--radius) * 2.2);
97	  --radius-4xl: calc(var(--radius) * 2.6);
98	}
99	
100	:root {
101	  /* Unconditional light/dark constants for --portfolio-bg — referenced by
102	       both the theme-conditional --portfolio-bg below and the theme-sweep
103	       probes in Footer.astro, so there's one source of truth for these two
104	       hex values regardless of which theme is currently active. */
105	  --portfolio-bg-light: #fff9f2;
106	  --portfolio-bg-dark: #18181b;
107	
108	  /* Portfolio theme (light) — from the light-mode Figma frame */
109	  --portfolio-bg: var(--portfolio-bg-light);
110	  --portfolio-bg-gradient: none;
111	  --portfolio-ink: #18181b;
112	  /* Single dim/secondary tone (consolidated from the old muted/muted-2/
113	       footnote/nav-muted split — all four did the same job at slightly
114	       different, sometimes-contrast-failing shades). #6b6b6b on the light
115	       bg computes to 5.1:1, passing WCAG AA-normal (4.5:1) with margin. */
116	  --portfolio-muted: #6b6b6b;
117	  /* Deeper teal than the dark-mode accent — #40C6B0 only hits 2.02:1 on
118	       this light bg (fails badly); #0F7A6B computes to 5.0:1. */
119	  --portfolio-accent: #0f7a6b;
120	  --portfolio-keycap: rgba(24, 24, 27, 0.1);
121	  --portfolio-nav-active: rgba(24, 24, 27, 0.08);
122	
123	  --radius: 0.625rem;
124	
125	  /* "Media frame" elevation — the shadow recipe every piece of inline
126	       case-study media shares (LoopVideo, LightboxImage, the Lightbox
127	       overlay, ProjectLayout's old embed box). Figma names this token
128	       "Light theme/Elevation" here and "Dark theme/Elevation" in .dark
129	       below — a flatter, single-tone drop shadow in light mode (no inset
130	       bevel; that only reads against a dark surface) vs. the dark theme's
131	       deeper shadow-plus-inner-highlight combination. */
132	  --media-frame-shadow:
133	    0px 3px 6px 0px rgba(0, 0, 0, 0.2), 0px 0px 0.5px 0px rgba(0, 0, 0, 0.15);
134	
135	  /* The same drop-shadow recipe as --media-frame-shadow's outer layers, written
136	       as a `filter` instead of a `box-shadow`. A box-shadow follows the element's
137	       rectangular box, but the project "cartridge" tiles are clipped to a stepped
138	       pixel shape; a drop-shadow filter on a wrapper follows that shape instead. */
139	  --cartridge-shadow: drop-shadow(0px 3px 6px rgba(0, 0, 0, 0.2))
140	    drop-shadow(0px 0px 0.5px rgba(0, 0, 0, 0.15));
141	
142	  /* Pressed ("depressed") button elevation — the raised --media-frame-shadow
143	       collapses to a tight, low shadow while a button is :active, which
144	       together with the scale-down reads as the button sinking toward the
145	       page. Used by ActionButton.astro. */
146	  --button-shadow-pressed:
147	    0px 1px 2px 0px rgba(0, 0, 0, 0.2), 0px 0px 0.5px 0px rgba(0, 0, 0, 0.15);
148	
149	  /* Lightbox overlay backdrop — a warm near-white scrim in light mode so
150	       it reads against the light page behind it, vs. the dark theme's
151	       near-black scrim below. Unlike --media-frame-shadow above, this one
152	       genuinely needs to flip per theme (the old dark-only rgba(24,24,27,.7)
153	       looked wrong once the rest of the page went light). */
154	  --lightbox-backdrop: oklch(98.8% 0.00852 67.7deg / 70%);
155	
156	  /* Case-study section stroke — a plain 1px outline (e.g. "The problem"
157	       in Ping). Figma's dark-mode value (#3c3c44) is a light-on-dark gray
158	       border; in light mode there's no equivalent Figma frame, so this is a
159	       low-opacity tint of --portfolio-ink instead, kept subtle enough to
160	       read as a hairline rather than a heavy outline. */
161	  --section-border-color: rgba(24, 24, 27, 0.15);
162	}
163	
164	.dark {
165	  /* Portfolio theme (dark) — from the dark-mode Figma frame */
166	  --portfolio-bg: var(--portfolio-bg-dark);
167	  --media-frame-shadow:
168	    0px 4px 7px 0px rgba(0, 0, 0, 0.85), 0px 1px 2px 0px rgba(0, 0, 0, 0.5),
169	    inset 0px 0.5px 0px 0px rgba(255, 255, 255, 0.1),
170	    inset 0px 0px 0.5px 0px rgba(255, 255, 255, 0.3);
171	  --cartridge-shadow: drop-shadow(0px 4px 7px rgba(0, 0, 0, 0.85))
172	    drop-shadow(0px 1px 2px rgba(0, 0, 0, 0.5));
173	  --lightbox-backdrop: rgba(24, 24, 27, 0.7);
174	  --section-border-color: #3c3c44;
175	  --portfolio-bg-gradient: linear-gradient(to bottom, #242429, #18181b);
176	  --portfolio-ink: #fff9f2;
177	  /* #BBBBBB on this bg computes to 9.23:1 — the same value the old
178	       footnote-only token already used, since it worked well here. */
179	  --portfolio-muted: #bbbbbb;
180	  --portfolio-accent: #40c6b0;
181	  --portfolio-keycap: rgba(255, 249, 242, 0.16);
182	  --portfolio-nav-active: rgba(255, 249, 242, 0.12);
183	  --button-shadow-pressed:
184	    0px 1px 2px 0px rgba(0, 0, 0, 0.6),
185	    inset 0px 0.5px 0px 0px rgba(255, 255, 255, 0.1),
186	    inset 0px 0px 0.5px 0px rgba(255, 255, 255, 0.3);
187	}
188	
189	/* ─── Page grid ───────────────────────────────────────────────────────────────
190	   Figma lays every page out as a fixed-width column with a left gutter: the
191	   top nav, the page content and the bottom action bar all start at the same x,
192	   to the right of the gutter (which holds labels or a side nav).
193	     --page-max     width of the column, gutter included
194	     --page-gutter  space on the column's left, before the content starts
195	   Each page sets these through `<body data-page="...">` (see BaseLayout). The
196	   gutter only exists from the lg breakpoint up; below that, pages are a single
197	   column and the gutter is 0. */
198	:root {
199	  --page-max: 1200px;
200	  --page-gutter: 0px;
201	  /* Space above the nav row inside the 80px sticky header: Figma puts the nav
202	     41px down on the Projects page and 56px down on the other pages. */
203	  --nav-top: 41px;
204	}
205	/* About: a plain 1200px column with the nav 56px down, as in Figma. */
206	body[data-page="about"] {
207	  --nav-top: 56px;
208	}
209	@media (min-width: 64rem) {
210	  /* Home / Projects: 990px column, 176px gutter (152px label column + 24px gap). */
211	  body[data-page="home"] {
212	    --page-max: 990px;
213	    --page-gutter: 176px;
214	  }
215	}
216	
217	@media (min-width: 64rem) {
218	  /* Case study: a 1200px column. Past the Overview, a 260px side nav + 40px gap
219	     fill the left gutter (300px) and the top nav starts after it; the bottom
220	     action bar starts 10px further in. On the Overview there's no side nav: the
221	     nav spans the full width and the action bar centers under the 900px body
222	     column (150px in, plus the same 10px). Changing section animates between
223	     the two (see the transitions on the nav). */
224	  body[data-page="case-study"] {
225	    --page-max: 1200px;
226	    --page-gutter: 300px;
227	    --bottom-gutter: 310px;
228	    --bottom-gap: 37px;
229	    --nav-top: 56px;
230	  }
231	  body[data-page="case-study"][data-section="overview"] {
232	    --page-gutter: 0px;
233	    --bottom-gutter: 160px;
234	  }
235	}
236	
237	@layer base {
238	  html {
239	    @apply font-sans;
240	  }
241	  /* Gradient-aware portfolio background — bg-portfolio-bg only sets a flat
242	     background-color, but dark mode needs a background-image gradient too.
243	     `none` in light mode means only the flat color paints. */
244	  .bg-portfolio-page {
245	    background-color: var(--portfolio-bg);
246	    background-image: var(--portfolio-bg-gradient);
247	  }
248	
249	  /* Shared headline treatment for every big Redaction-35 title on the site
250	     (home page's "Hi, I'm Cody", case-study titles).
251	     font-size is plain CSS, not a Tailwind arbitrary value — Tailwind v4's
252	     arbitrary-value parser can't handle the commas inside clamp(), even
253	     backslash-escaped, and silently drops the whole class instead of
254	     erroring. clamp() scales the size smoothly from 64px on small screens
255	     up to 80px, rather than snapping at a single breakpoint the way the
256	     home page's old text-[56px] sm:text-[80px] did — the 3vw term hits the
257	     64px floor around a 533px-wide viewport and the 80px ceiling around
258	     1067px, transitioning linearly in between. */
259	  .portfolio-headline {
260	    font-family: var(--font-redaction);
261	    font-size: clamp(4rem, 3rem + 3vw, 5rem);
262	    line-height: 0.94;
263	    letter-spacing: -2.4px;
264	    color: var(--portfolio-ink);
265	  }
266	
267	  /* Inline `code` spans (MDX backtick syntax, e.g. case studies referencing
268	     component/prop names like `Card`) — site-wide, not scoped to any one
269	     layout's prose wrapper. */
270	  code {
271	    font-family: var(--font-mono);
272	    border-radius: 4px;
273	    padding: 4px;
274	    background-color: oklch(94.5% 0.044 73.9deg);
275	  }
276	
277	  .dark code {
278	    background-color: oklch(33.5% 0.0104 286deg);
279	  }
280	}
281	
282	/* Per-project icon/badge colors (index.astro, ProjectLayout.astro) come from
283	   MDX frontmatter and can optionally differ by theme — same --x-light/--x-dark
284	   -> --x resolution pattern as --portfolio-bg above, except these are set
285	   inline per-element (from content data) rather than globally in :root/.dark,
286	   so the resolution rule has to live here instead of alongside --portfolio-bg. */
287	[style*="--icon-color-light"] {
288	  --icon-color: var(--icon-color-light);
289	}
290	[style*="--badge-color-light"] {
291	  --badge-color: var(--badge-color-light);
292	}
293	.dark [style*="--icon-color-dark"] {
294	  --icon-color: var(--icon-color-dark);
295	}
296	.dark [style*="--badge-color-dark"] {
297	  --badge-color: var(--badge-color-dark);
298	}
299	
300	@media (prefers-reduced-motion: no-preference) {
301	  [data-animate] {
302	    opacity: 0;
303	  }
304	}
305	
306	/* Theme-toggle sweep, driven by the View Transitions API (see the click
307	   handler in Footer.astro). The browser snapshots the page before and after
308	   the .dark class toggles into ::view-transition-old(root) and
309	   ::view-transition-new(root); overriding the default cross-fade with a
310	   clip-path keyframe reveals the new-theme screenshot as an expanding line
311	   sweeping across, with the old screenshot sitting untouched underneath —
312	   so each side of the line is already showing its correct final theme. */
313	::view-transition-old(root),
314	::view-transition-new(root) {
315	  animation: none;
316	  mix-blend-mode: normal;
317	}
318	
319	::view-transition-old(root) {
320	  z-index: 1;
321	}
322	
323	::view-transition-new(root) {
324	  z-index: 2;
325	}
326	
327	[data-theme-sweep-direction="light"]::view-transition-new(root) {
328	  animation: theme-sweep-up 500ms ease-in-out forwards;
329	}
330	
331	[data-theme-sweep-direction="dark"]::view-transition-new(root) {
332	  animation: theme-sweep-down 500ms ease-in-out forwards;
333	}
334	
335	@keyframes theme-sweep-up {
336	  from {
337	    clip-path: inset(100% 0 0 0);
338	  }
339	  to {
340	    clip-path: inset(0 0 0 0);
341	  }
342	}
343	
344	@keyframes theme-sweep-down {
345	  from {
346	    clip-path: inset(0 0 100% 0);
347	  }
348	  to {
349	    clip-path: inset(0 0 0 0);
350	  }
351	}
352	
353	/* Approach section's scroll-triggered grid background (see
354	   .ping-section--approach::before in ProjectLayout.astro) — a plain
355	   opacity fade, played once when the section's .grid-active class is
356	   added by observeGridReveal() in src/lib/animations.ts. */
357	@keyframes gridSequence {
358	  from {
359	    opacity: 0;
360	  }
361	  to {
362	    opacity: 1;
363	  }
364	}
365

1	---
2	// ProjectShowcase.astro — the home page: a row of large project icon buttons
3	// ("cartridges") across the top, and a preview of the selected project under it.
4	//
5	// Each project has its own URL (/home/<slug>), and /home itself shows the
6	// first project. Selecting an icon is an ordinary link click handled by
7	// Astro's client-side router, which swaps the preview underneath while the
8	// icon bar — marked `transition:persist` — stays in the DOM. Because the same
9	// element survives, CSS transitions animate the new selection growing and the
10	// old one shrinking, and a small script slides the bar so the selected icon
11	// stays in view.
12	//
13	// Layout follows Figma's "Home — Library" frame: a column whose left gutter
14	// (176px at lg+, see "Page grid" in global.css) holds the meta labels, with the
15	// icon bar, title, headline and values all starting at the column's left edge.
16	import { getCollection } from "astro:content";
17	import { Clock } from "pixelarticons/react/Clock";
18	import { Play } from "pixelarticons/react/Play";
19	import { projectIconMap } from "@/lib/projectIconMap";
20	import { slashList, typeIcon } from "@/lib/projectMeta";
21	
22	interface Props {
23	  // Which project to preview. Omit for the first one (the /home page).
24	  slug?: string;
25	}
26	
27	const projects = (
28	  await getCollection("projects", ({ data }) => data.published)
29	).sort((a, b) => a.data.order - b.data.order);
30	
31	const current = projects.find((p) => p.id === Astro.props.slug) ?? projects[0];
32	const { data } = current;
33	const TypeIcon = data.type ? typeIcon(data.type) : null;
34	
35	// Per-project colors are passed as inline custom properties; global.css
36	// resolves them to --icon-color / --badge-color for the active theme.
37	function colorVars(d: (typeof projects)[number]["data"]) {
38	  return {
39	    ...(d.iconColor ? { "--icon-color-light": d.iconColor } : {}),
40	    ...(d.iconColorDark ? { "--icon-color-dark": d.iconColorDark } : {}),
41	    ...(d.badgeColor ? { "--badge-color-light": d.badgeColor } : {}),
42	    ...(d.badgeColorDark ? { "--badge-color-dark": d.badgeColorDark } : {}),
43	  };
44	}
45	
46	// "Project Ping" -> "Ping" for the small label under each icon.
47	const shortName = (name: string) => name.replace(/^Project\s+/, "");
48	
49	// Split the headline around the accent phrase so it can be italicized and
50	// tinted in the project's own color.
51	const tagline = data.tagline;
52	const accentIndex = data.accentPhrase ? tagline.indexOf(data.accentPhrase) : -1;
53	const before = accentIndex >= 0 ? tagline.slice(0, accentIndex) : tagline;
54	const after =
55	  accentIndex >= 0
56	    ? tagline.slice(accentIndex + (data.accentPhrase?.length ?? 0))
57	    : "";
58	---
59	
60	<main
61	  style="max-width: calc(var(--page-max) + 3rem);"
62	  class="mx-auto w-full px-6 pt-[70px] pb-8"
63	>
64	  <!-- Icon bar. Persisted across navigations (see the header comment). From lg
65	       up its left padding is the page gutter, which lines the first tile up with
66	       the text column below; on smaller screens it just scrolls sideways. -->
67	  <nav
68	    transition:persist="project-bar"
69	    aria-label="Projects"
70	    data-project-bar
71	    class="project-bar -mx-6 flex items-center gap-6 overflow-x-auto px-6 lg:pl-[calc(1.5rem+var(--page-gutter))]"
72	  >
73	    {
74	      projects.map((project, index) => {
75	        const Icon = projectIconMap[project.data.icon];
76	        return (
77	          <a
78	            href={`/home/${project.id}`}
79	            data-project-tile
80	            data-slug={project.id}
81	            data-first={index === 0 ? "" : undefined}
82	            aria-label={project.data.name}
83	            aria-current={project.id === current.id ? "page" : undefined}
84	            class="project-tile flex shrink-0 flex-col items-start gap-2"
85	            style={colorVars(project.data)}
86	          >
87	            <span class="tile-wrap">
88	              <span class="tile flex items-center justify-center">
89	                <Icon />
90	              </span>
91	            </span>
92	            <span class="tile-label">{shortName(project.data.name)}</span>
93	          </a>
94	        );
95	      })
96	    }
97	    <!-- Placeholder for future projects; not a link. -->
98	    <div
99	      class="project-tile project-tile--soon flex shrink-0 flex-col items-start gap-2"
100	    >
101	      <span class="tile-wrap">
102	        <span class="tile flex items-center justify-center">
103	          <Clock />
104	        </span>
105	      </span>
106	      <span class="tile-label">Coming soon</span>
107	    </div>
108	  </nav>
109	
110	  <!-- The preview. Everything marked data-animate fades up in sequence each
111	       time a project is shown (see runFadeUpStagger in lib/animations.ts). -->
112	  <section
113	    style={colorVars(data)}
114	    class="mt-8 flex flex-col gap-8 lg:pl-[var(--page-gutter)]"
115	  >
116	    <div class="flex max-w-[888px] flex-col gap-6">
117	      <p data-animate class="preview-name">{data.name}</p>
118	
119	      <h1 data-animate class="preview-headline">
120	        {before}
121	        {
122	          accentIndex >= 0 && (
123	            <span class="italic" style="color: var(--icon-color);">
124	              {data.accentPhrase}
125	            </span>
126	          )
127	        }
128	        {after}
129	      </h1>
130	    </div>
131	
132	    <p data-animate class="preview-description">
133	      {data.summary ?? data.description}
134	    </p>
135	  </section>
136	
137	  <!-- Details: a 640px block whose labels sit in the gutter (152px column) and
138	       whose values start at the content column (24px gap), per Figma. Each row
139	       is its own grid so the chip rows can center their label against the chip
140	       while the text rows (role, scope) align on the text baseline. -->
141	  <dl style={colorVars(data)} class="meta-grid mt-[84px]">
142	    {
143	      data.type && (
144	        <div class="meta-row">
145	          <dt data-animate class="meta-label">
146	            Type
147	          </dt>
148	          <dd data-animate class="m-0">
149	            <span class="meta-badge">
150	              {TypeIcon && <TypeIcon width={16} height={16} />}
151	              {data.type}
152	            </span>
153	          </dd>
