199	<style>
200	  .project-bar {
201	    /* Hide the scrollbar but keep the bar scrollable on narrow screens. */
202	    scrollbar-width: none;
203	  }
204	  .project-bar::-webkit-scrollbar {
205	    display: none;
206	  }
207	
208	  /* ─── Cartridge tiles ──────────────────────────────────────────────────── */
209	  /* Figma's tiles aren't rounded squares: each corner is a little pixel
210	     staircase. --u is the size of one stair step; the clip-path below uses 3
211	     steps per corner. It's registered as a <length> so it can animate when a
212	     tile grows from small to selected. */
213	  @property --u {
214	    syntax: "<length>";
215	    inherits: true;
216	    initial-value: 1.5px;
217	  }
218	
219	  .tile {
220	    --u: 1.5px;
221	    --tile-size: 72px;
222	    --icon-size: 32px;
223	    width: var(--tile-size);
224	    height: var(--tile-size);
225	    /* Unselected: the project color at 15% (same tint as the detail chips). */
226	    background-color: color-mix(in srgb, var(--icon-color) 15%, transparent);
227	    color: var(--icon-color);
228	    clip-path: polygon(
229	      calc(var(--u) * 3) 0,
230	      calc(100% - var(--u) * 3) 0,
231	      calc(100% - var(--u) * 3) var(--u),
232	      calc(100% - var(--u) * 2) var(--u),
233	      calc(100% - var(--u) * 2) calc(var(--u) * 2),
234	      calc(100% - var(--u)) calc(var(--u) * 2),
235	      calc(100% - var(--u)) calc(var(--u) * 3),
236	      100% calc(var(--u) * 3),
237	      100% calc(100% - var(--u) * 3),
238	      calc(100% - var(--u)) calc(100% - var(--u) * 3),
239	      calc(100% - var(--u)) calc(100% - var(--u) * 2),
240	      calc(100% - var(--u) * 2) calc(100% - var(--u) * 2),
241	      calc(100% - var(--u) * 2) calc(100% - var(--u)),
242	      calc(100% - var(--u) * 3) calc(100% - var(--u)),
243	      calc(100% - var(--u) * 3) 100%,
244	      calc(var(--u) * 3) 100%,
245	      calc(var(--u) * 3) calc(100% - var(--u)),
246	      calc(var(--u) * 2) calc(100% - var(--u)),
247	      calc(var(--u) * 2) calc(100% - var(--u) * 2),
248	      var(--u) calc(100% - var(--u) * 2),
249	      var(--u) calc(100% - var(--u) * 3),
250	      0 calc(100% - var(--u) * 3),
251	      0 calc(var(--u) * 3),
252	      var(--u) calc(var(--u) * 3),
253	      var(--u) calc(var(--u) * 2),
254	      calc(var(--u) * 2) calc(var(--u) * 2),
255	      calc(var(--u) * 2) var(--u),
256	      calc(var(--u) * 3) var(--u)
257	    );
258	  }
259	  .tile :global(svg) {
260	    width: var(--icon-size);
261	    height: var(--icon-size);
262	  }
263	  .project-tile--soon .tile {
264	    background-color: var(--portfolio-keycap);
265	    color: var(--portfolio-muted);
266	  }
267	
268	  /* The selected tile: 128px, solid project color, cream icon at 56px, with a
269	     drop shadow on its wrapper (clip-path would cut off a box-shadow). */
270	  .project-tile[aria-current="page"] .tile {
271	    --u: 2.5px;
272	    --tile-size: 128px;
273	    --icon-size: 56px;
274	    background-color: var(--icon-color);
275	    color: #fff9f2;
276	  }
277	  .project-tile[aria-current="page"] .tile-wrap {
278	    filter: var(--cartridge-shadow);
279	  }
280	
281	  /* Labels: 12px mono, 0.5px tracking, truncated to the 72px tile width. The
282	     selected tile keeps its (invisible) label so the column stays 152px tall,
283	     which is what vertically centers the smaller tiles beside it. */
284	  .tile-label {
285	    width: 72px;
286	    height: 16px;
287	    overflow: hidden;
288	    text-overflow: ellipsis;
289	    white-space: nowrap;
290	    font-family: var(--font-mono);
291	    font-size: 12px;
292	    letter-spacing: 0.5px;
293	    color: var(--portfolio-muted);
294	  }
295	  .project-tile[aria-current="page"] .tile-label {
296	    visibility: hidden;
297	  }
298	
299	  a.project-tile:not([aria-current="page"]):hover .tile {
300	    transform: translateY(-2px);
301	  }
302	
303	  @media (prefers-reduced-motion: no-preference) {
304	    .tile {
305	      transition:
306	        width 0.35s cubic-bezier(0.22, 1, 0.36, 1),
307	        height 0.35s cubic-bezier(0.22, 1, 0.36, 1),
308	        --u 0.35s cubic-bezier(0.22, 1, 0.36, 1),
309	        background-color 0.25s ease-out,
310	        color 0.25s ease-out,
311	        transform 0.2s ease-out;
312	    }
313	    .tile :global(svg) {
314	      transition:
315	        width 0.35s cubic-bezier(0.22, 1, 0.36, 1),
316	        height 0.35s cubic-bezier(0.22, 1, 0.36, 1);
317	    }
318	  }
319	
320	  a.project-tile:focus {
321	    outline: none;
322	  }
323	  a.project-tile:focus-visible .tile-wrap {
324	    outline: 2px solid var(--icon-color, currentColor);
325	    outline-offset: 3px;
326	  }
327	
328	  /* ─── Preview text ─────────────────────────────────────────────────────── */
329	  .preview-name {
330	    margin: 0;
331	    font-family: var(--font-mono);
332	    font-size: 20px;
333	    line-height: 1.4;
334	    letter-spacing: -0.2px;
335	    color: var(--portfolio-ink);
336	  }
337	  /* Redaction 35 at 64px on desktop (scaling down on smaller screens), 0.94
338	     line height, -1.92px tracking. No text-wrap balancing: Figma lets the line
339	     fill the column, so "Rethinking how users know" stays on one line. */
340	  .preview-headline {
341	    margin: 0;
342	    font-family: var(--font-redaction);
343	    font-size: clamp(2.75rem, 1.2rem + 4.2vw, 4rem);
344	    font-weight: 400;
345	    line-height: 0.94;
346	    letter-spacing: -0.03em;
347	    color: var(--portfolio-ink);
348	  }
349	  .preview-description {
350	    margin: 0;
351	    max-width: 620px;
352	    font-family: var(--font-plex-sans);
353	    font-size: 18px;
354	    line-height: 28px;
355	    color: color-mix(in srgb, var(--portfolio-ink) 85%, transparent);
356	  }
357	
358	  /* ─── Details ──────────────────────────────────────────────────────────── */
359	  /* Rows 17px apart; within a row, labels take a 152px column and values start
360	     after a 24px gap. Stacked (label above value) below lg, where there's no
361	     gutter. */
362	  .meta-grid {
363	    display: flex;
364	    flex-direction: column;
365	    gap: 1rem;
366	    max-width: 640px;
367	  }
368	  .meta-row {
369	    display: grid;
370	    grid-template-columns: 1fr;
371	    gap: 0.25rem 24px;
372	    align-items: center;
373	  }
374	  .meta-row--text {
375	    align-items: baseline;
376	  }
377	  @media (min-width: 64rem) {
378	    .meta-grid {
379	      gap: 17px;
380	    }
381	    .meta-row {
382	      grid-template-columns: 152px minmax(0, 1fr);
383	    }
384	  }
385	
386	  /* Figma sets all of these in IBM Plex Mono at its "normal" line height (about
387	     1.3), not the 1.5 the base styles would otherwise give them. */
388	  .meta-label {
389	    font-family: var(--font-mono);
390	    font-size: 14px;
391	    line-height: normal;
392	    text-transform: uppercase;
393	    color: var(--portfolio-muted);
394	  }
395	  .meta-value {
396	    margin: 0;
397	    font-family: var(--font-mono);
398	    font-size: 14px;
399	    line-height: normal;
400	    text-transform: uppercase;
401	    color: var(--portfolio-ink);
402	  }
403	  /* Scope is a longer run of text: 24px line height, wrapping in the value column. */
404	  .meta-value--wrap {
405	    line-height: 24px;
406	  }
407	  /* The chips: 15% project-color fill, 8px/3px padding, 4px corners. */
408	  .meta-badge {
409	    /* Block-level (not inline-flex) so the surrounding <dd> doesn't add a line
410	       box around it, which would make each chip row taller than the chip. */
411	    display: flex;
412	    width: fit-content;
413	    align-items: center;
414	    gap: 6px;
415	    padding: 3px 8px;
416	    border-radius: 4px;
417	    background-color: color-mix(in srgb, var(--icon-color) 15%, transparent);
418	    color: var(--portfolio-ink);
419	    font-family: var(--font-mono);
420	    font-size: 14px;
421	    font-weight: 500;
422	    line-height: normal;
423	  }
424	  .meta-badge :global(svg) {
425	    color: var(--icon-color);
426	  }
427	</style>
428	
429	<script>
430	  // Keeps the persisted icon bar in sync with the page: marks the tile for the
431	  // current URL as selected and slides the bar so it's in view. Runs on first
432	  // load and after every client-side navigation.
433	  document.addEventListener("astro:page-load", () => {
434	    const bar = document.querySelector<HTMLElement>("[data-project-bar]");
435	    if (!bar) return;
436	
437	    const tiles = [...bar.querySelectorAll<HTMLElement>("[data-project-tile]")];
438	    // /home and /home/<slug>. /home alone means "the first project".
439	    const slug = location.pathname.match(/^\/home\/([^/]+)/)?.[1];
440	    const active = tiles.find((t) =>
441	      slug ? t.dataset.slug === slug : t.hasAttribute("data-first"),
442	    );
443	    if (!active) return;
444	
445	    const alreadyActive = active.getAttribute("aria-current") === "page";
446	    tiles.forEach((t) => {
447	      if (t === active) t.setAttribute("aria-current", "page");
448	      else t.removeAttribute("aria-current");
449	    });
450	
451	    // Slide the bar (not the page) so the selected tile sits in the middle.
452	    // 128 is the selected tile's final width (see the CSS above), so the
453	    // math doesn't depend on where the width transition currently is.
454	    const left = active.offsetLeft - (bar.clientWidth - 128) / 2;
455	    const reduce = window.matchMedia(
456	      "(prefers-reduced-motion: reduce)",
457	    ).matches;
458	    bar.scrollTo({
459	      left: Math.max(0, left),
460	      behavior: reduce || alreadyActive ? "auto" : "smooth",
461	    });
462	  });
463	</script>
