2	// TopNav.astro — site-wide header, shown on every page except the start page.
3	//
4	// Left:  Projects / About. The current section is bold + ink-colored and gets
5	//        aria-current="page".
6	// Right: a live local date + time, links to GitHub, Discord and LinkedIn, and
7	//        the theme toggle (moon in dark mode, sun in light mode) at the far end.
8	//
9	// The <header> below has `transition:persist`, so its DOM survives
10	// client-side navigations (no flicker, the clock keeps ticking). Because the
11	// server-rendered "current" state would then go stale, a small script below
12	// re-computes aria-current on every navigation.
13	import { GitBranch } from "pixelarticons/react/GitBranch";
14	import { User } from "pixelarticons/react/User";
15	import { MoonStar } from "pixelarticons/react/MoonStar";
16	import { Sun } from "pixelarticons/react/Sun";
17	import SocialLinks from "@/components/SocialLinks.astro";
18	import { ABOUT_HREF, PROJECTS_HREF } from "@/data/links";
19	
20	const pathname = Astro.url.pathname;
21	const section = pathname.startsWith(ABOUT_HREF) ? "about" : "projects";
22	
23	const navItems = [
24	  { id: "projects", label: "Projects", href: PROJECTS_HREF, Icon: GitBranch },
25	  { id: "about", label: "About", href: ABOUT_HREF, Icon: User },
26	];
27	---
28	
29	<header
30	  transition:persist="top-nav"
31	  style="max-width: calc(var(--page-max) + 3rem);"
32	  class="top-nav sticky top-0 z-50 mx-auto h-20 w-full px-6 pt-[var(--nav-top)]"
33	>
34	  <!-- The inner row is inset by the page gutter (see "Page grid" in global.css),
35	       so the nav starts at the same x as the page content, as in Figma. -->
36	  <div
37	    class="flex h-6 items-center justify-between gap-4 lg:pl-[var(--page-gutter)]"
38	  >
39	    <nav aria-label="Primary" class="flex items-center gap-6">
40	      {
41	        navItems.map(({ id, label, href, Icon }) => (
42	          <a
43	            href={href}
44	            data-nav={id}
45	            aria-current={section === id ? "page" : undefined}
46	            class="top-nav-item text-portfolio-muted flex items-center gap-3 font-mono text-sm"
47	          >
48	            <Icon width={24} height={24} />
49	            <span>{label}</span>
50	          </a>
51	        ))
52	      }
53	    </nav>
54	
55	    <!-- Date/time, social links, then the theme toggle at the far right. -->
56	    <div class="flex items-center gap-4">
57	      <!-- Filled in by the script below. min-w reserves the width so the
58	           icons next to it don't shift when the text first appears. Hidden on
59	           phones, where there isn't room for it beside the icons. -->
60	      <time
61	        data-clock
62	        class="font-plex-sans text-portfolio-muted hidden min-w-[4.625rem] text-xs tabular-nums sm:block"
63	      ></time>
64	      <SocialLinks class="gap-2" />
65	      <button
66	        type="button"
67	        data-theme-toggle
68	        aria-label="Toggle light and dark theme"
69	        class="theme-toggle bg-portfolio-keycap text-portfolio-ink flex size-6 cursor-pointer items-center justify-center rounded-sm"
70	      >
71	        <MoonStar width={16} height={16} className="hidden dark:block" />
72	        <Sun width={16} height={16} className="block dark:hidden" />
73	      </button>
74	    </div>
75	  </div>
76	</header>
77	
78	<style>
79	  /* Sticky header that slides away while reading down the page and returns as
80	     soon as you scroll back up (script below toggles data-hidden). The soft
81	     fade behind it keeps page content from colliding with the nav items. */
82	  .top-nav {
83	    transition: transform 0.3s ease-out;
84	  }
85	  /* Only painted once the page has scrolled, so at the very top the header
86	     sits directly on the page's own background with no visible band. */
87	  .top-nav[data-scrolled] {
88	    background-image: linear-gradient(
89	      to bottom,
90	      var(--portfolio-bg) 55%,
91	      transparent
92	    );
93	  }
94	  .top-nav[data-hidden] {
95	    transform: translateY(-100%);
96	  }
97	  @media (prefers-reduced-motion: reduce) {
98	    .top-nav {
99	      transition: none;
100	    }
101	  }
102	
103	  /* Current page: bold + full ink color. Everything else stays muted. */
104	  .top-nav-item[aria-current="page"] {
105	    color: var(--portfolio-ink);
106	    font-weight: 600;
107	  }
108	  /* The inner row's left inset changes between case-study sections (the side
109	     nav is absent on the Overview); slide rather than jump. */
110	  @media (prefers-reduced-motion: no-preference) {
111	    .top-nav > div {
112	      transition: padding-left 0.35s cubic-bezier(0.22, 1, 0.36, 1);
113	    }
114	  }
115	  .theme-toggle {
116	    transition: background-color 0.2s ease-out;
117	  }
118	  .theme-toggle:hover {
119	    background-color: color-mix(in srgb, var(--portfolio-ink) 24%, transparent);
120	  }
121	  .top-nav-item:not([aria-current="page"]):hover {
122	    color: var(--portfolio-ink);
123	  }
124	</style>
125	
126	<script>
127	  import { toggleTheme } from "@/lib/theme";
128	
129	  // Event delegation: one listener on the document finds the toggle button,
130	  // so it works however many times the header is re-rendered or persisted.
131	  document.addEventListener("click", (event) => {
132	    if ((event.target as Element).closest("[data-theme-toggle]")) {
133	      toggleTheme();
134	    }
135	  });
136	
137	  // ─── Live clock ──────────────────────────────────────────────────────────
138	  // Local date + 24-hour time, e.g. "Nov 24 11:37".
139	  const dateFormat = new Intl.DateTimeFormat("en-US", {
140	    month: "short",
141	    day: "numeric",
142	  });
143	  const timeFormat = new Intl.DateTimeFormat("en-US", {
144	    hour: "2-digit",
145	    minute: "2-digit",
146	    hour12: false,
147	  });
148	
149	  function renderClock() {
150	    const now = new Date();
151	    const text = `${dateFormat.format(now)} ${timeFormat.format(now)}`;
152	    document.querySelectorAll<HTMLElement>("[data-clock]").forEach((el) => {
153	      el.textContent = text;
154	    });
155	  }
156	
157	  // Re-render exactly on each minute boundary instead of polling every
158	  // second: the displayed text only changes once a minute.
159	  function scheduleTick() {
160	    renderClock();
161	    setTimeout(scheduleTick, 60_000 - (Date.now() % 60_000));
162	  }
163	  scheduleTick();
164	  // Also paint right after navigations, in case Astro swapped in a fresh
165	  // (empty) <time> element instead of keeping the persisted one.
166	  document.addEventListener("astro:page-load", renderClock);
167	
168	  // ─── Hide on scroll down, show on scroll up ──────────────────────────────
169	  // Both bars (this header and the fixed bottom action bar) are visible on
170	  // load, slide away while reading down the page, and return as soon as you
171	  // scroll back up (Figma: "Nav on initial load and on scroll up"). Only starts
172	  // hiding once you're past the top of the page, and ignores tiny scroll
173	  // jitters (< 6px) so it doesn't flicker.
174	  let lastY = window.scrollY;
175	  window.addEventListener(
176	    "scroll",
177	    () => {
178	      const header = document.querySelector<HTMLElement>(".top-nav");
179	      if (!header) return;
180	      const bars = [
181	        header,
182	        ...document.querySelectorAll<HTMLElement>(".bottom-nav"),
183	      ];
184	      const y = window.scrollY;
185	      header.toggleAttribute("data-scrolled", y > 8);
186	      if (Math.abs(y - lastY) < 6) return;
187	      const hide = y > lastY && y > 120;
188	      bars.forEach((bar) => bar.toggleAttribute("data-hidden", hide));
189	      lastY = y;
190	    },
191	    { passive: true },
192	  );
193	
194	  // ─── Active nav item ─────────────────────────────────────────────────────
195	  // Runs on first load and after every client-side navigation.
196	  document.addEventListener("astro:page-load", () => {
197	    const current = location.pathname.startsWith("/about")
198	      ? "about"
199	      : "projects";
200	    document.querySelectorAll<HTMLElement>("[data-nav]").forEach((el) => {
201	      if (el.dataset.nav === current) {
202	        el.setAttribute("aria-current", "page");
203	      } else {
204	        el.removeAttribute("aria-current");
205	      }
206	    });
207	  });
208	</script>
