2	// ProjectLayout.astro — wraps an individual project's case-study page.
3	//
4	// A case study is one page made of four full-screen sections the reader
5	// scrolls through, with CSS scroll-snap aligning each to the top of the
6	// screen:
7	//   Overview     — an oversized title-slide presentation (Overview.astro)
8	//   Deep dive    — the write-up: the MDX body passed in through <slot />
9	//   Walkthrough  — the Loom recording (Walkthrough.astro)
10	//   Gallery      — every still and loop in one grid (Gallery.astro)
11	// A side nav (SubNav.astro) tracks the current section, and the bottom nav
12	// swaps its actions per section. The scroll-tracking lives in
13	// src/lib/caseStudy.ts.
14	import BaseLayout from "@/layouts/BaseLayout.astro";
15	import Lightbox from "@/components/Lightbox.astro";
16	import SubNav from "@/components/case-study/SubNav.astro";
17	import Overview from "@/components/case-study/Overview.astro";
18	import Walkthrough from "@/components/case-study/Walkthrough.astro";
19	import Gallery from "@/components/case-study/Gallery.astro";
20	import MobileSectionBar from "@/components/MobileSectionBar.astro";
21	import type { NavAction } from "@/layouts/BottomNav.astro";
22	import type { ComponentType, SVGProps } from "react";
23	
24	interface GalleryItem {
25	  kind: "image" | "video";
26	  src?: string;
27	  webm?: string;
28	  mp4?: string;
29	  alt: string;
30	  label: string;
31	  caption: string;
32	}
33	
34	interface Props {
35	  slug: string;
36	  name: string;
37	  tagline: string;
38	  icon: ComponentType<SVGProps<SVGSVGElement>>;
39	  iconColor?: string;
40	  iconColorDark?: string;
41	  badgeColor?: string;
42	  badgeColorDark?: string;
43	  description?: string;
44	  accentPhrase?: string;
45	  loomUrl?: string;
46	  role?: string;
47	  scope?: string;
48	  type?: string;
49	  heroArt?: "toasts" | "mark" | "cpu-card";
50	  gallery?: GalleryItem[];
51	  // The project the "Next project" action leads to (wraps around to the first).
52	  next?: { slug: string; name: string };
53	}
54	
55	const {
56	  slug,
57	  name,
58	  tagline,
59	  icon,
60	  iconColor,
61	  iconColorDark,
62	  badgeColor,
63	  badgeColorDark,
64	  description,
65	  accentPhrase,
66	  loomUrl,
67	  role,
68	  scope,
69	  type,
70	  heroArt,
71	  gallery = [],
72	  next,
73	} = Astro.props;
74	
75	const hasWalkthrough = Boolean(loomUrl);
