102	// preview), the same in every section. The Overview's own "Read deep dive /
103	// Watch walkthrough / View gallery" actions are buttons inside that section.
104	const actions: NavAction[] = [
105	  ...(next
106	    ? [
107	        {
108	          label: "Next project",
109	          detail: next.name.replace(/^Project\s+/, ""),
110	          shortcut: "x",
111	          href: `/projects/${next.slug}`,
112	        },
113	      ]
114	    : []),
