218	<script>
219	  import { observeGridReveal } from "@/lib/animations";
220	  import { initCaseStudy } from "@/lib/caseStudy";
221	
222	  // Runs on first load and after every client-side navigation, so each case
223	  // study you open re-binds scroll tracking, replays the Overview entrance, and
224	  // animates the "Approach" dot grid.
225	  document.addEventListener("astro:page-load", () => {
226	    initCaseStudy();
227	    observeGridReveal();
