2	// Overview.astro — the case study's opening "presentation" (Figma: the
3	// "Project — Detail" frames). From top to bottom:
4	//   1. a centered hero: per-project artwork, an oversized headline with the
5	//      accent phrase in the project color, and a small project chip
6	//   2. the description
7	//   3. a two-column row: an action menu (Read deep dive / Watch walkthrough /
8	//      View gallery) on the left, the project's type, role and scope on the right
9	//
10	// The menu items are real buttons with keyboard shortcuts (Enter / W / G), so
11	// they don't need entries in the bottom nav. The `data-ov` attributes are hooks
12	// for the entrance animation in src/lib/caseStudy.ts (built with Motion).
13	import type { ComponentType, SVGProps } from "react";
14	import { Play } from "pixelarticons/react/Play";
15	import ActionButton from "@/components/ActionButton.astro";
16	import HeroArt from "@/components/case-study/hero/HeroArt.astro";
17	import { slashList, typeIcon } from "@/lib/projectMeta";
18	
19	interface Props {
20	  name: string;
21	  tagline: string;
22	  accentPhrase?: string;
23	  description?: string;
24	  icon: ComponentType<SVGProps<SVGSVGElement>>;
25	  heroArt?: "toasts" | "mark" | "cpu-card";
26	  type?: string;
27	  role?: string;
28	  scope?: string;
29	  hasWalkthrough?: boolean;
30	  hasGallery?: boolean;
31	}
32	
33	const {
34	  name,
35	  tagline,
36	  accentPhrase,
37	  description,
38	  icon: Icon,
39	  heroArt,
40	  type,
41	  role,
42	  scope,
43	  hasWalkthrough,
44	  hasGallery,
45	} = Astro.props;
46	
47	const TypeIcon = type ? typeIcon(type) : null;
48	
49	// Split the headline into words (so each can animate in on its own), marking
50	// the words that fall inside the accent phrase.
51	const accentStart = accentPhrase ? tagline.indexOf(accentPhrase) : -1;
52	const accentEnd =
53	  accentStart >= 0 ? accentStart + (accentPhrase?.length ?? 0) : -1;
54	let cursor = 0;
55	const words = tagline.split(" ").map((text) => {
56	  const start = cursor;
57	  cursor += text.length + 1;
58	  const accent = accentStart >= 0 && start >= accentStart && start < accentEnd;
59	  return { text, accent };
60	});
