1	---
2	// BottomNav.astro — persistent bar of context-aware actions along the bottom
3	// of the viewport. Each page decides which actions it offers by passing an
4	// `actions` list to BaseLayout; this component just renders them as
5	// ActionButtons. The pages that shouldn't have it (start, about) pass none,
6	// and BaseLayout skips rendering this component entirely.
7	import ActionButton from "@/components/ActionButton.astro";
8	
9	export interface NavAction {
10	  label: string;
11	  // Shorter label for narrow screens.
12	  shortLabel?: string;
13	  // Keyboard key that triggers the action: "enter", "esc", or a single letter.
14	  shortcut: string;
15	  href: string;
16	  // Dimmed text after the label (e.g. the next project's name).
17	  detail?: string;
18	  // Render filled at rest (the page's primary action).
19	  featured?: boolean;
20	  // Only show while one of these case-study sections is active (space
21	  // separated ids in the DOM). Omit to always show. The case-study script
22	  // toggles the `hidden` attribute as the reader scrolls.
23	  sections?: string[];
24	}
25	
26	interface Props {
27	  actions: NavAction[];
28	}
29	
30	const { actions } = Astro.props;
31	---
32	
33	<nav
34	  aria-label="Page actions"
35	  class="bottom-nav pointer-events-none fixed inset-x-0 bottom-0 z-40 pt-10 pb-5 sm:pb-[58px]"
36	>
37	  <div
38	    style="max-width: calc(var(--page-max) + 3rem);"
39	    class="bottom-actions pointer-events-auto mx-auto flex w-full items-center gap-x-2 overflow-x-auto px-6 sm:gap-x-[var(--bottom-gap,1.5rem)] lg:pl-[calc(1.5rem+var(--bottom-gutter,var(--page-gutter)))]"
40	  >
41	    {
42	      actions.map((action) => (
43	        <ActionButton
44	          label={action.label}
45	          shortLabel={action.shortLabel}
46	          detail={action.detail}
47	          shortcut={action.shortcut}
48	          href={action.href}
49	          featured={action.featured}
50	          shape={action.featured ? "pill" : "rounded"}
51	          data-sections={action.sections?.join(" ")}
52	          hidden={
53	            action.sections ? !action.sections.includes("overview") : undefined
54	          }
55	        />
56	      ))
57	    }
58	  </div>
59	</nav>
60	
61	<style>
62	  /* One row, never wrapping: on phones with several actions it scrolls
63	     sideways instead of stacking up over the page content. */
64	  .bottom-actions {
65	    scrollbar-width: none;
66	  }
67	  /* The left inset changes between case-study sections; slide rather than jump. */
68	  @media (prefers-reduced-motion: no-preference) {
69	    .bottom-actions {
70	      transition: padding-left 0.35s cubic-bezier(0.22, 1, 0.36, 1);
71	    }
72	  }
73	  /* If a row is still wider than the screen, fade its right edge as a hint
74	     that it scrolls. (When everything fits, the fade lands on empty padding.) */
75	  @media (max-width: 39.99rem) {
76	    .bottom-actions {
77	      mask-image: linear-gradient(
78	        to right,
79	        black calc(100% - 2rem),
80	        transparent
81	      );
82	    }
83	  }
84	  .bottom-actions::-webkit-scrollbar {
85	    display: none;
86	  }
87	  /* A soft fade behind the bar so page content scrolling underneath it
88	     doesn't collide with the button labels. The gradient only paints the
89	     bar's own padding area; the middle of the viewport stays untouched. */
90	  /* Slides down out of view while reading down the page; TopNav's scroll
91	     script toggles data-hidden on both bars. The bar is inert while away, so
92	     its (invisible) buttons can't be clicked or tabbed to; the keyboard
93	     shortcuts still work. */
94	  .bottom-nav {
95	    transition:
96	      transform 0.3s ease-out,
97	      visibility 0.3s;
98	  }
99	  .bottom-nav[data-hidden] {
100	    transform: translateY(100%);
101	    visibility: hidden;
102	  }
103	  @media (prefers-reduced-motion: reduce) {
104	    .bottom-nav {
105	      transition: none;
106	    }
107	  }
108	  .bottom-nav {
109	    background-image: linear-gradient(
110	      to top,
111	      var(--portfolio-bg) 40%,
112	      transparent
113	    );
114	  }
115	</style>
