1	---
2	// ActionButton.astro — the "secondary" button from Figma's "New buttons"
3	// section: transparent at rest, and on hover/focus it fills with the theme's
4	// ink color (text flips to the page color) and lifts with the shared
5	// --media-frame-shadow. A small key-cap tile on the left tells the visitor
6	// which keyboard key triggers the same action.
7	//
8	// Renders an <a> when `href` is given, otherwise a <button>.
9	//
10	// Keyboard shortcuts: pass `shortcut`. We stamp it on the element as
11	// `data-shortcut`, and the single global listener in src/lib/shortcuts.ts
12	// finds the element and clicks it. That means a page never wires up key
13	// handlers itself — it only declares buttons.
14	import { ArrowReturnLeft } from "pixelarticons/react/ArrowReturnLeft";
15	
16	interface Props {
17	  label: string;
18	  // Shorter text used instead of `label` below the sm breakpoint, where space
19	  // is tight (e.g. "Walkthrough" for "Watch walkthrough").
20	  shortLabel?: string;
21	  // Dimmed text after the label, e.g. the next project's name.
22	  detail?: string;
23	  // "enter" and "esc" get their special glyphs; anything else is shown as an
24	  // uppercase single character (e.g. "x", "w").
25	  shortcut?: "enter" | "esc" | (string & {});
26	  href?: string;
27	  // Pill shape (Start page) vs. the slightly squarer bottom-nav shape.
28	  shape?: "pill" | "rounded";
29	  // Always-filled look (the same as hover), for the page's primary action.
30	  featured?: boolean;
31	  // The large, full-width "menu item" form used in the case-study Overview:
32	  // 18px text, a pill with 16px/12px padding, label on the left and the key
33	  // tile pushed to the far right.
34	  block?: boolean;
35	  hidden?: boolean;
36	  class?: string;
37	  id?: string;
38	  [key: `data-${string}`]: string | boolean | undefined;
39	}
40	
41	const {
42	  label,
43	  shortLabel,
44	  detail,
45	  shortcut,
46	  href,
47	  shape = "rounded",
48	  featured = false,
49	  block = false,
50	  class: className,
51	  id,
52	  ...rest
53	} = Astro.props;
54	
55	const Tag = href ? "a" : "button";
56	const keyName = shortcut?.toLowerCase();
57	---
58	
59	<Tag
60	  id={id}
61	  href={href}
62	  type={href ? undefined : "button"}
63	  data-shortcut={keyName}
64	  class:list={[
65	    "action-button text-portfolio-ink inline-flex shrink-0 cursor-pointer items-center font-mono whitespace-nowrap",
66	    block
67	      ? // Large menu item: 360px-ish pill, label left, key tile right. Only the
68	        // filled primary item is medium weight and full-strength ink; the rest are
69	        // regular weight at 80% ink.
70	        [
71	          "w-full justify-between gap-3 rounded-full px-4 py-3 text-lg leading-[normal]",
72	          featured ? "font-medium" : "text-portfolio-ink/80 font-normal",
73	        ]
74	      : [
75	          "text-base font-medium",
76	          // Figma: the filled (primary) look is 12px/8px padding with a 4px icon
77	          // gap; the plain secondary look is 8px padding with a 12px gap.
78	          featured ? "gap-1 px-3 py-2" : "gap-3 p-2",
79	          // Corners: fully round for the pill shape, otherwise 8px.
80	          shape === "pill" ? "rounded-full" : "rounded-md",
81	        ],
82	    featured && "is-featured",
83	    block && "is-block",
84	    className,
85	  ]}
86	  {...rest}
87	>
88	  {
89	    shortcut && (
90	      <span
91	        aria-hidden="true"
92	        class:list={[
93	          "keycap bg-portfolio-keycap flex h-6 items-center justify-center rounded-sm",
94	          // In the block form the key tile sits at the far right, after the label.
95	          block && "order-last",
96	          // ESC is three letters wide; every other key is a square tile.
97	          keyName === "esc" ? "w-10 text-xs tracking-wider" : "w-6",
98	        ]}
99	      >
100	        {keyName === "enter" ? (
101	          <ArrowReturnLeft width={18} height={18} />
102	        ) : keyName === "esc" ? (
103	          "ESC"
104	        ) : (
105	          <span class="text-sm">{keyName?.toUpperCase()}</span>
106	        )}
107	      </span>
108	    )
109	  }
110	  <span>
111	    {
112	      shortLabel ? (
113	        <>
114	          <span class="max-sm:hidden">{label}</span>
115	          <span class="sm:hidden">{shortLabel}</span>
116	        </>
117	      ) : (
118	        label
119	      )
120	    }
121	    {detail && <span class="text-portfolio-muted"> {detail}</span>}
122	  </span>
123	</Tag>
124	
125	<style>
126	  .action-button {
127	    background-color: transparent;
128	    box-shadow: none;
129	    /* The transition lives on the resting selector, not :active, so it plays
130	       on press AND on release. */
131	    transition:
132	      transform 0.15s ease-out,
133	      box-shadow 0.15s ease-out,
134	      background-color 0.15s ease-out,
135	      color 0.15s ease-out;
136	  }
137	
138	  /* Browsers show the default focus ring on some mouse clicks (Safari); we
139	     only want a ring for keyboard focus, and hover/focus-visible already
140	     share the filled look below. */
141	  .action-button:focus {
142	    outline: none;
143	  }
144	
145	  .action-button:hover,
146	  .action-button:focus-visible,
147	  .action-button.is-featured {
148	    background-color: var(--portfolio-ink);
149	    color: var(--portfolio-bg);
150	    box-shadow: var(--media-frame-shadow);
151	  }
152	
153	  /* While the button is filled with ink, the key-cap and the dimmed detail
154	     text need to follow the inverted colors, or they'd vanish. */
155	  .action-button:hover :global(.bg-portfolio-keycap),
156	  .action-button:focus-visible :global(.bg-portfolio-keycap) {
157	    background-color: color-mix(in srgb, var(--portfolio-bg) 18%, transparent);
158	  }
159	  /* On the always-filled primary look Figma shows the arrow directly on the
160	     fill, with no tile behind it. */
161	  .action-button.is-featured :global(.bg-portfolio-keycap) {
162	    background-color: transparent;
163	  }
164	  .action-button:hover :global(.text-portfolio-muted),
165	  .action-button:focus-visible :global(.text-portfolio-muted),
166	  .action-button.is-featured :global(.text-portfolio-muted) {
167	    color: color-mix(in srgb, var(--portfolio-bg) 55%, transparent);
168	  }
169	
170	  /* "Depress on click": shrink slightly and collapse the shadow so the
171	     button sinks toward the page. */
172	  .action-button:active {
173	    transform: scale(0.97);
174	    box-shadow: var(--button-shadow-pressed);
175	  }
176	
177	  /* No keyboard to show shortcuts for: on touch devices and very narrow
178	     screens the key-cap is dropped (the action still works by tapping), and
179	     the button gets a little more side padding so the label doesn't crowd. */
180	  @media (hover: none), (max-width: 39.99rem) {
181	    .action-button :global(.keycap) {
182	      display: none;
183	    }
184	    /* The compact bottom-nav buttons shrink; the large Overview menu items keep
185	       their size. */
186	    .action-button:not(.is-block) {
187	      gap: 0;
188	      padding: 0.5rem 0.75rem;
189	      font-size: 0.875rem;
190	    }
191	  }
192	
193	  @media (prefers-reduced-motion: reduce) {
194	    .action-button {
