1	---
2	// SubNav.astro — the case study's side navigation (Figma "Sub-nav").
3	//
4	// Four top-level items: Overview, Deep dive, Walkthrough, Gallery. "Deep dive"
5	// owns sub-items (Intro, The problem, ...) that only expand while the reader
6	// is inside that section. The script in src/lib/caseStudy.ts keeps this in
7	// sync with scrolling: it sets `data-active-section` on this <nav> (which the
8	// CSS below uses to expand the sub-items) and `aria-current` on the links.
9	interface Props {
10	  hasWalkthrough?: boolean;
11	  hasGallery?: boolean;
12	}
13	
14	const { hasWalkthrough = true, hasGallery = true } = Astro.props;
15	
16	// The ids match the `id`s on the corresponding blocks in the MDX body.
17	const deepDiveItems = [
18	  { id: "intro", label: "Intro" },
19	  { id: "problem", label: "The problem" },
20	  { id: "solution", label: "The solution" },
21	  { id: "approach", label: "The approach" },
22	  { id: "examples", label: "Examples" },
23	  { id: "postscript", label: "Postscript" },
24	];
25	---
26	
27	<nav
28	  aria-label="Case study sections"
29	  data-subnav
30	  class="subnav font-mono text-sm"
31	>
32	  <a href="#overview" data-section-link="overview" class="subnav-link">
33	    Overview
34	  </a>
35	
36	  <a href="#deep-dive" data-section-link="deep-dive" class="subnav-link">
37	    Deep dive
38	  </a>
39	  <!-- Sub-items. The grid-rows 0fr -> 1fr trick animates height without
40	       knowing it: the inner wrapper has overflow hidden and min-height 0. -->
41	  <div class="subnav-children">
42	    <ul class="subnav-tree m-0 list-none p-0">
43	      {
44	        deepDiveItems.map((item) => (
45	          <li>
46	            <a
47	              href={`#${item.id}`}
48	              data-sub-link={item.id}
49	              class="subnav-link subnav-sublink"
50	            >
51	              {item.label}
52	            </a>
53	          </li>
54	        ))
55	      }
56	    </ul>
57	  </div>
58	
59	  {
60	    hasWalkthrough && (
61	      <a
62	        href="#walkthrough"
63	        data-section-link="walkthrough"
64	        class="subnav-link"
65	      >
66	        Walkthrough
67	      </a>
68	    )
69	  }
70	  {
71	    hasGallery && (
72	      <a href="#gallery" data-section-link="gallery" class="subnav-link">
73	        Gallery
74	      </a>
75	    )
76	  }
77	</nav>
78	
79	<style>
80	  .subnav {
81	    --subnav-line: color-mix(in srgb, var(--portfolio-ink) 85%, transparent);
82	    display: flex;
83	    flex-direction: column;
84	    gap: 0.5rem;
85	    width: 260px;
86	  }
87	
88	  .subnav-link {
89	    display: block;
90	    padding: 0.5rem 0.75rem;
91	    border-radius: 0.5rem;
92	    color: var(--portfolio-muted);
93	    transition:
94	      background-color 0.2s ease-out,
95	      color 0.2s ease-out;
96	  }
97	  .subnav-link:hover {
98	    color: var(--portfolio-ink);
99	  }
100	  .subnav-link:focus {
101	    outline: none;
102	  }
103	  .subnav-link:focus-visible {
104	    outline: 2px solid var(--portfolio-ink);
105	    outline-offset: -2px;
106	  }
107	  /* Current top-level item: tinted pill, bold + full ink color. */
108	  .subnav-link[aria-current="true"] {
109	    background-color: var(--portfolio-nav-active);
110	    color: var(--portfolio-ink);
111	    font-weight: 600;
112	    /* Figma's pill has stepped, pixel-style corners (6px deep, in 1.5 / 1.5 / 3px
113	       bands) rather than a smooth radius. */
114	    border-radius: 0;
115	    clip-path: polygon(
116	      6px 0,
117	      calc(100% - 6px) 0,
118	      calc(100% - 6px) 1.5px,
119	      calc(100% - 4px) 1.5px,
120	      calc(100% - 4px) 3px,
121	      calc(100% - 2px) 3px,
122	      calc(100% - 2px) 6px,
123	      100% 6px,
124	      100% calc(100% - 6px),
125	      calc(100% - 2px) calc(100% - 6px),
126	      calc(100% - 2px) calc(100% - 3px),
127	      calc(100% - 4px) calc(100% - 3px),
128	      calc(100% - 4px) calc(100% - 1.5px),
129	      calc(100% - 6px) calc(100% - 1.5px),
130	      calc(100% - 6px) 100%,
131	      6px 100%,
132	      6px calc(100% - 1.5px),
133	      4px calc(100% - 1.5px),
134	      4px calc(100% - 3px),
135	      2px calc(100% - 3px),
136	      2px calc(100% - 6px),
137	      0 calc(100% - 6px),
138	      0 6px,
139	      2px 6px,
140	      2px 3px,
141	      4px 3px,
142	      4px 1.5px,
143	      6px 1.5px
144	    );
145	  }
146	
147	  /* ─── Deep dive sub-items ───────────────────────────────────────────────── */
148	  .subnav-children {
149	    display: grid;
150	    grid-template-rows: 0fr;
151	    margin-top: -0.5rem; /* cancels the flex gap so a collapsed list adds no space */
152	    transition: grid-template-rows 0.3s ease-out;
153	  }
154	  .subnav-tree {
155	    min-height: 0;
156	    overflow: hidden;
157	    position: relative;
158	    display: flex;
159	    flex-direction: column;
160	    gap: 0.5rem;
161	    visibility: hidden;
162	    transition: visibility 0.3s;
163	  }
164	  .subnav[data-active-section="deep-dive"] .subnav-children {
165	    grid-template-rows: 1fr;
166	    margin-top: 0;
167	  }
168	  .subnav[data-active-section="deep-dive"] .subnav-tree {
169	    visibility: visible;
170	  }
171	
172	  /* Tree connector (Figma: a 1px line at x=13, with a rounded elbow leading into
173	     each sub-item). The line runs from just inside the first item to where the
174	     last elbow starts; each elbow is a 12px box with a left and bottom edge. */
175	  .subnav-tree::before {
176	    content: "";
177	    position: absolute;
178	    left: 13px;
179	    top: 2px;
180	    bottom: 29px;
181	    width: 1px;
182	    background: var(--subnav-line);
183	  }
184	  .subnav-sublink {
185	    position: relative;
186	    padding-left: 2rem;
187	  }
188	  .subnav-sublink::before {
189	    content: "";
190	    position: absolute;
191	    left: 13px;
192	    top: 5px;
193	    width: 12px;
194	    height: 12.5px;
195	    border-left: 1px solid var(--subnav-line);
196	    border-bottom: 1px solid var(--subnav-line);
197	    border-bottom-left-radius: 4px;
198	  }
199	  /* Current sub-item: bold ink, no pill (the pill belongs to "Deep dive"). */
200	  .subnav-sublink[aria-current="true"] {
201	    background-color: transparent;
202	  }
203	
204	  @media (prefers-reduced-motion: reduce) {
205	    .subnav-link,
206	    .subnav-children,
207	    .subnav-tree {
208	      transition: none;
209	    }
210	  }
211	</style>
212

