2	// Walkthrough.astro — the case study's video walkthrough: the project's Loom
3	// recording embedded in a framed 16:9 player (12px corners), top-aligned with the other sections
4	// at the 160px content line.
5	import { MEDIA_FRAME_SHADOW } from "@/lib/media";
6	
7	interface Props {
8	  // Loom share URL (loom.com/share/<id>). The player needs /embed/<id>.
9	  loomUrl: string;
10	  name: string;
11	}
12	
13	const { loomUrl, name } = Astro.props;
14	const embedSrc = loomUrl.replace("/share/", "/embed/");
