16	
17	<div
18	  class="relative aspect-video w-full overflow-hidden rounded-xl"
19	  style={{ boxShadow: MEDIA_FRAME_SHADOW }}
20	>
21	  <!-- loading="lazy": the video is a whole screen away on first load, so don't
22	       pay for Loom's player until the reader gets close to it. -->
23	  <iframe
24	    src={embedSrc}
25	    title={`${name} video walkthrough`}
26	    loading="lazy"
27	    allow="fullscreen; picture-in-picture"
28	    allowfullscreen
29	    class="absolute inset-0 block size-full border-0"></iframe>
30	</div>
