1	---
2	// Gallery.astro — every still and loop from the case study in one grid, each
3	// with a short label + caption (e.g. "BEFORE  Small, limited popover").
4	// Stills open in the shared Lightbox, same as in the deep dive.
5	import LightboxImage from "@/components/case-study/LightboxImage.astro";
6	import LoopVideo from "@/components/case-study/LoopVideo.astro";
