8	interface GalleryItem {
9	  kind: "image" | "video";
10	  src?: string;
11	  webm?: string;
12	  mp4?: string;
13	  alt: string;
14	  label: string;
15	  caption: string;
16	}
17	
18	interface Props {
19	  items: GalleryItem[];
20	}
21	
22	const { items } = Astro.props;
23	---
24	
25	<!-- Figma: two 442px columns with a 16px gutter; every tile is a 276px-tall crop
26	     with a 12px mono caption 12px below it, and rows sit 16px apart. -->
27	<div class="grid grid-cols-1 gap-4 sm:grid-cols-2">
28	  {
29	    items.map((item) => (
30	      <figure class="m-0 flex min-w-0 flex-col gap-3">
31	        {item.kind === "image" && item.src ? (
32	          <LightboxImage src={item.src} alt={item.alt} flat />
33	        ) : item.webm && item.mp4 ? (
34	          <LoopVideo webm={item.webm} mp4={item.mp4} flat />
35	        ) : null}
36	        <figcaption class="font-mono text-xs leading-4 uppercase">
37	          <span class="text-portfolio-ink font-semibold">{item.label}</span>
38	          {item.caption && (
39	            <span class="text-portfolio-muted"> {item.caption}</span>
40	          )}
