1	---
2	// LabeledRow.astro — the numbered "From X to Y" feature heading (Figma
3	// "Feature title" + description): a small project-colored number, then the
4	// title in Plex Mono, with the description in Plex Sans underneath.
5	//
6	// The number comes from a CSS counter (reset on `.article-body` in
7	// ProjectLayout.astro), so rows count up 01, 02, 03 in reading order without
8	// each MDX file having to number them by hand.
9	// Postscript.astro's rows look similar but are laid out as label | text columns,
10	// so they're styled separately there.
11	interface Props {
12	  label: string;
13	}
14	
15	const { label } = Astro.props;
16	---
17	
18	<div class="labeled-row flex w-full flex-col items-start gap-4">
19	  <div
20	    class="feature-title text-portfolio-ink m-0 flex w-full items-baseline gap-3 font-mono text-xl leading-7 font-medium"
21	  >
22	    <span class="feature-number shrink-0 text-sm leading-5"></span>
23	    <span class="min-w-0 flex-1">{label}</span>
24	  </div>
25	  <div
26	    class="font-plex-sans text-portfolio-ink/85 min-w-0 text-lg leading-7 font-normal [&_p]:mb-4 [&_p:last-child]:mb-0"
27	  >
28	    <slot />
29	  </div>
30	</div>
31	
32	<style>
33	  .labeled-row {
34	    counter-increment: feature;
35	  }
36	  /* The article's own paragraph rules (light 18/32) are for long-form copy; the
37	     feature descriptions are Regular 18/28. */
38	  .labeled-row :global(p) {
39	    margin: 0;
40	    font-weight: 400;
41	    line-height: 28px;
42	  }
43	  .feature-number {
44	    color: var(--icon-color);
45	  }
46	  .feature-number::before {
47	    content: counter(feature, decimal-leading-zero);
48	  }
49	</style>
