1	---
2	// Postscript.astro — closing section every case study ends with (Figma
3	// "Takeaways"). Three rows (Why it worked / Key takeaway / Project status),
4	// each a hairline divider, then a small icon + mono label on the left and the
5	// copy on the right. The three labels are fixed across every project; only the
6	// row content passed in via slots changes.
7	// The icons pick up the project color through --icon-color, like the headline's
8	// accent phrase; `iconColor`/`iconColorDark` let a caller override it.
9	import { CircleQuestion } from "pixelarticons/react/CircleQuestion";
10	import { Key } from "pixelarticons/react/Key";
11	import { XpBar } from "pixelarticons/react/XpBar";
12	
13	interface Props {
14	  iconColor?: string;
15	  iconColorDark?: string;
16	}
17	
18	const { iconColor, iconColorDark } = Astro.props;
19	
20	const colorVars = {
21	  ...(iconColor ? { "--icon-color-light": iconColor } : {}),
22	  ...(iconColorDark ? { "--icon-color-dark": iconColorDark } : {}),
23	};
24	---
25	
26	<section class="postscript" style={colorVars}>
27	  <div class="row">
28	    <div class="label">
29	      <CircleQuestion width={16} height={16} />
30	      <span>Why it worked</span>
31	    </div>
32	    <div class="copy"><slot name="why-it-worked" /></div>
33	  </div>
34	  <div class="row">
35	    <div class="label">
36	      <Key width={16} height={16} />
37	      <span>Key takeaway</span>
38	    </div>
39	    <div class="copy"><slot name="key-takeaway" /></div>
40	  </div>
41	  <div class="row">
42	    <div class="label">
43	      <XpBar width={16} height={16} />
44	      <span>Project status</span>
45	    </div>
46	    <div class="copy"><slot name="project-status" /></div>
47	  </div>
48	</section>
49	
50	<style>
51	  .postscript {
52	    padding-top: 60px;
53	  }
54	  /* Divider above each row: ink at 14% (Figma: cream at 14%). */
55	  .row {
56	    display: flex;
57	    flex-direction: column;
58	    gap: 12px;
59	    padding: 28px 0;
60	    border-top: 1px solid
61	      color-mix(in srgb, var(--portfolio-ink) 14%, transparent);
62	  }
63	  @media (min-width: 40rem) {
64	    .row {
65	      flex-direction: row;
66	      gap: 40px;
67	    }
68	  }
69	  /* 16px icon, 8px gap, then a 180px-wide label: a 204px column. */
70	  .label {
71	    display: flex;
72	    flex: none;
73	    align-items: center;
74	    gap: 8px;
75	    height: 20px;
76	    color: var(--portfolio-muted);
77	    font-family: var(--font-mono);
78	    font-size: 14px;
79	    line-height: 20px;
80	    text-transform: uppercase;
81	  }
82	  @media (min-width: 40rem) {
83	    .label {
84	      width: 204px;
85	    }
86	  }
87	  .label :global(svg) {
88	    flex: none;
89	    color: var(--icon-color);
90	  }
91	  .copy {
92	    display: flex;
93	    flex: 1 1 0;
94	    min-width: 0;
95	    flex-direction: column;
96	    gap: 16px;
97	    font-family: var(--font-plex-sans);
98	    font-size: 18px;
99	    font-weight: 400;
100	    line-height: 28px;
101	    color: var(--portfolio-ink);
102	  }
103	  /* The article's own paragraph rules (light 18/32, with extra margins) are
104	     meant for the long-form copy above; the takeaways use their own rhythm. */
105	  .postscript .copy :global(p),
106	  .postscript .copy :global(p + p) {
107	    margin: 0;
108	    font-weight: 400;
109	    line-height: 28px;
110	  }
111	  /* MDX wraps a slotted <Fragment> in an empty paragraph; it would add a gap. */
112	  .postscript .copy :global(p:empty) {
113	    display: none;
114	  }
115	</style>
