1	---
2	// LoopVideo.astro — silent, looping, autoplaying inline video used to
3	// illustrate a case-study beat (Figma "Video" frame: 4px corners on a neutral
4	// surface, with a small "LOOP · 5S" tag in the top-left corner).
5	//
6	// The tag's length is read from the video itself once its metadata loads, so
7	// no one has to keep a hand-typed duration in sync with the file.
8	interface Props {
9	  webm: string;
10	  mp4: string;
11	  caption?: string;
12	  // Gallery tile: a 276px-tall, 8px-cornered crop with no loop tag.
13	  flat?: boolean;
14	}
15	
16	const { webm, mp4, caption, flat = false } = Astro.props;
17	---
18	
19	<figure class="m-0 flex flex-col gap-4">
20	  <div
21	    class:list={[
22	      "loop-video relative overflow-hidden",
23	      flat ? "rounded-md" : "rounded-[4px]",
24	    ]}
25	  >
26	    <video
27	      class:list={["block w-full", flat ? "h-[276px] object-cover" : "h-auto"]}
28	      autoplay
29	      loop
30	      muted
31	      playsinline
32	    >
33	      <source src={webm} type="video/webm" />
34	      <source src={mp4} type="video/mp4" />
35	    </video>
36	    {
37	      !flat && (
38	        <span class="loop-tag" hidden>
39	          LOOP
40	        </span>
41	      )
42	    }
43	  </div>
44	  {
45	    caption && (
46	      <figcaption class="font-plex-sans text-portfolio-ink text-base leading-6">
47	        {caption}
48	      </figcaption>
49	    )
50	  }
51	</figure>
52	
53	<style>
54	  .loop-video {
55	    background-color: color-mix(in srgb, var(--portfolio-ink) 8%, transparent);
56	  }
57	  /* A frosted cream chip with dark mono text, in both themes (it sits on top
58	     of the video, not the page). */
59	  .loop-tag {
60	    position: absolute;
61	    top: 8px;
62	    left: 8px;
63	    padding: 3px 8px;
64	    border-radius: 3px;
65	    background-color: rgba(255, 249, 242, 0.7);
66	    color: #18181b;
67	    font-family: var(--font-mono);
68	    font-size: 12px;
69	    font-weight: 500;
70	    line-height: 16px;
71	    white-space: nowrap;
72	  }
73	</style>
74	
75	<script>
76	  // "LOOP · 5S" / "LOOP · 6.5S": whole seconds drop the decimal.
77	  function labelLoops() {
78	    document.querySelectorAll<HTMLElement>(".loop-video").forEach((box) => {
79	      const video = box.querySelector("video");
80	      const tag = box.querySelector<HTMLElement>(".loop-tag");
81	      if (!video || !tag || tag.dataset.ready) return;
82	      const apply = () => {
83	        if (!Number.isFinite(video.duration)) return;
84	        const secs = Math.round(video.duration * 2) / 2;
85	        tag.textContent = `LOOP · ${secs}S`;
86	        tag.hidden = false;
87	        tag.dataset.ready = "true";
88	      };
89	      if (video.readyState >= 1) apply();
90	      else video.addEventListener("loadedmetadata", apply, { once: true });
91	    });
92	  }
93	  document.addEventListener("astro:page-load", labelLoops);
94	</script>
