1	// shortcuts.ts — one global keyboard listener for the whole site.
2	//
3	// Instead of each page registering its own key handlers, buttons declare
4	// their key with a `data-shortcut` attribute (see ActionButton.astro). When
5	// a key is pressed we look for a matching element on the *current* page and
6	// click it. Because it looks at the live DOM on every keypress, it keeps
7	// working across client-side navigations with no re-binding.
8	
9	// Maps KeyboardEvent.key (lowercased) to the data-shortcut value.
10	const KEY_ALIASES: Record<string, string> = {
11	  escape: "esc",
12	};
13	
14	function isTypingTarget(el: EventTarget | null): boolean {
15	  if (!(el instanceof HTMLElement)) return false;
16	  return (
17	    el.isContentEditable ||
18	    el.tagName === "INPUT" ||
19	    el.tagName === "TEXTAREA" ||
20	    el.tagName === "SELECT"
21	  );
22	}
23	
24	function isInteractiveTarget(el: EventTarget | null): boolean {
25	  return (
26	    el instanceof HTMLElement && (el.tagName === "A" || el.tagName === "BUTTON")
27	  );
28	}
