30	export function initShortcuts() {
31	  // Module scripts only run once per full page load, but guard anyway so a
32	  // second import can never stack two listeners (which would double-click).
33	  const w = window as unknown as { __shortcutsBound?: boolean };
34	  if (w.__shortcutsBound) return;
35	  w.__shortcutsBound = true;
36	
37	  document.addEventListener("keydown", (event) => {
38	    if (event.defaultPrevented || event.repeat) return;
39	    // Leave browser/OS shortcuts (Cmd+W, Ctrl+X ...) alone.
40	    if (event.metaKey || event.ctrlKey || event.altKey) return;
41	    if (isTypingTarget(event.target)) return;
42	    // While a modal dialog (e.g. the lightbox) is open, keys belong to it:
43	    // Esc should close the dialog, not trigger the page's "Back" action.
44	    if (document.querySelector('[aria-modal="true"][aria-hidden="false"]')) {
45	      return;
46	    }
47	
48	    const raw = event.key.toLowerCase();
49	    const key = KEY_ALIASES[raw] ?? raw;
50	
51	    // A focused link/button already "clicks" itself on Enter, so firing our
52	    // handler too would trigger the action twice.
53	    if (key === "enter" && isInteractiveTarget(event.target)) return;
54	
55	    // Several buttons can share a key across a page's different states (e.g.
56	    // case-study actions that swap per section), so take the first one that
57	    // isn't hidden.
58	    const target = [
59	      ...document.querySelectorAll<HTMLElement>(
60	        `[data-shortcut="${CSS.escape(key)}"]`,
61	      ),
62	    ].find((el) => !el.closest("[hidden]"));
63	    if (!target) return;
64	
65	    event.preventDefault();
66	    target.click();
67	  });
